CREATE OR REPLACE FUNCTION dashboard_private.assert_timetable_operational_conflicts_v1()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare oldref jsonb; newref jsonb; x jsonb; y jsonb; d date; oldday jsonb; newday jsonb;
begin
 select reference into oldref from dashboard_private.timetable_operating_write_baselines where transaction_id=txid_current();
 if oldref is null then return;end if;
 newref:=dashboard_private.read_timetable_operating_reference_v1();
 -- A catalog or content write may change metadata while leaving every occupancy
 -- unchanged. This is the same no-new-occupancy outcome as the checks below.
 if oldref->'shadowSlots'=newref->'shadowSlots'
 and oldref->'datedSessions'=newref->'datedSessions'
 and oldref->'unresolvedOccupancies'=newref->'unresolvedOccupancies'
 and oldref->'datedUnresolvedOccupancies'=newref->'datedUnresolvedOccupancies' then return;end if;
 -- Introducing unknown occupancy is not a safe partial save. Existing unknown
 -- rows can remain unchanged or be removed/repaired without touching history.
 if exists(select b-'label' from jsonb_array_elements((newref->'unresolvedOccupancies')||(newref->'datedUnresolvedOccupancies')) b
           except select ob-'label' from jsonb_array_elements((oldref->'unresolvedOccupancies')||(oldref->'datedUnresolvedOccupancies')) ob) then
 raise exception using errcode='23P01',message='timetable_resource_conflict';end if;
 for x in select value from jsonb_array_elements(newref->'shadowSlots') loop
 if exists(select 1 from jsonb_array_elements(oldref->'shadowSlots') b where dashboard_private.timetable_occupancy_key_v1(b)=dashboard_private.timetable_occupancy_key_v1(x)) then continue;end if;
 if exists(select 1 from jsonb_array_elements((newref->'unresolvedOccupancies')||(newref->'datedUnresolvedOccupancies')) b where b->>'date' is null or ((b->>'date')::date >= (newref->>'asOfDate')::date and extract(dow from (b->>'date')::date)::int=(x->>'weekday')::int)) or exists(select 1 from jsonb_array_elements(newref->'shadowSlots') b where b->>'weekday'=x->>'weekday' and dashboard_private.timetable_intersects_v1(x,b)) then raise exception using errcode='23P01',message='timetable_resource_conflict';end if;
 end loop;
 -- All actual dates are checked, including sessions under closed/preparing classes.
 -- Comparing effective occupancy also detects a removed skipped override which
 -- newly exposes a weekly default at that date.
 for d in select distinct (value->>'date')::date from jsonb_array_elements((oldref->'datedSessions')||(newref->'datedSessions')) loop
 select coalesce(jsonb_agg(v),'[]') into oldday from dashboard_private.timetable_effective_date_v1(oldref,d) v;
 select coalesce(jsonb_agg(v),'[]') into newday from dashboard_private.timetable_effective_date_v1(newref,d) v;
 -- Multiplicity, not mere existence: newly exposed defaults and duplicate keys
 -- must still be checked. Compute each day's counts once against all its rows.
 for x in
 with old_counts as (
   select dashboard_private.timetable_occupancy_key_v1(v) key,count(*) n
   from jsonb_array_elements(oldday) v group by 1
 ), new_counts as (
   select dashboard_private.timetable_occupancy_key_v1(v) key,count(*) n,
          (jsonb_agg(v order by ord))->0 representative,min(ord) first_ordinal
   from jsonb_array_elements(newday) with ordinality entries(v,ord) group by 1
 )
 select representative from new_counts n left join old_counts o using(key)
 where n.n>coalesce(o.n,0) order by first_ordinal loop
 if exists(select 1 from jsonb_array_elements((newref->'unresolvedOccupancies')||(newref->'datedUnresolvedOccupancies')) b where (b->>'date' is null or (b->>'date')::date=d)) or exists(select 1 from jsonb_array_elements(newday) b where dashboard_private.timetable_intersects_v1(x,b)) then raise exception using errcode='23P01',message='timetable_resource_conflict';end if;
 end loop;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION dashboard_private.evaluate_timetable_transfer_v1(r jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source_id uuid:=(r#>>'{source,planId}')::uuid; target_id uuid:=(r#>>'{target,planId}')::uuid;
 source_snapshot jsonb; target_snapshot jsonb; ref jsonb; selected uuid[];
 i public.timetable_plan_items; s public.timetable_plan_slots; code text; label text;
 blockers jsonb:='[]'; warnings jsonb:='[]'; mappings jsonb:='[]'; pending_ids jsonb:='[]'; entry jsonb;
 keep_pending boolean:=r->>'onConflict'='keep_pending'; period_from date; period_to date;
begin
 source_snapshot:=public.get_timetable_plan_v1(source_id);
 if target_id is not null then target_snapshot:=public.get_timetable_plan_v1(target_id); end if;
 ref:=dashboard_private.read_timetable_operating_reference_v1();
 select array_agg(value::uuid order by value::uuid) into selected from jsonb_array_elements_text(r->'itemIds');
 if source_snapshot#>>'{plan,state}'<>'draft' or (target_id is not null and target_snapshot#>>'{plan,state}'<>'draft') then
   raise exception using errcode='42501',message='timetable_forbidden';
 end if;
 perform dashboard_private.timetable_check_capacity_v1(source_id);
 if target_id is not null then
   perform dashboard_private.timetable_check_capacity_v1(target_id);
   period_from:=(target_snapshot#>>'{plan,targetStartDate}')::date;
   period_to:=(target_snapshot#>>'{plan,targetEndDate}')::date;
   if (target_snapshot#>>'{capacity,itemCount}')::int+cardinality(selected)>500 then
     raise exception using errcode='22023',message='timetable_capacity'; end if;
 else period_from:=(ref->>'asOfDate')::date; period_to:='infinity'::date;
 end if;
 foreach source_id in array selected loop
   select * into i from public.timetable_plan_items where id=source_id and plan_id=(r#>>'{source,planId}')::uuid;
   if not found or i.state<>'draft' then raise exception using errcode='22023',message='timetable_invalid'; end if;
   mappings:=mappings||jsonb_build_array(jsonb_build_object('sourceId',i.id,'action',case when target_id is null then 'create_active_class' else 'create_plan_item' end));
   if jsonb_array_length(i.pending_slots)>0 or not exists(select 1 from public.timetable_plan_slots where item_id=i.id) then
     entry:=jsonb_build_object('sourceId',i.id,'code','unplaced','label','미배치 슬롯을 모두 해결하세요.','relatedIds','[]'::jsonb);
     if keep_pending then warnings:=warnings||jsonb_build_array(entry); else blockers:=blockers||jsonb_build_array(entry); end if;
   end if;
   if target_id is null and ((select count(*) from public.timetable_plan_slots where item_id=i.id)>64
     or (i.subject='과학' and (i.grade not in('고1','고2','고3') or i.subject_area_key is null))
     or (i.subject<>'과학' and i.subject_area_key is not null)
     or (i.subject_area_key is not null and not exists(select 1 from public.academic_subject_areas a where a.subject=i.subject and a.area_key=i.subject_area_key and a.is_active))) then
     blockers:=blockers||jsonb_build_array(jsonb_build_object('sourceId',i.id,'code','metadata','label','수업 기본정보 또는 배치 개수를 확인하세요.','relatedIds','[]'::jsonb));
   end if;
   for s in select * from public.timetable_plan_slots where item_id=i.id order by id loop
     code:=null; label:=null;
     if not exists(select 1 from public.teacher_catalogs t where t.id=s.teacher_catalog_id and t.is_visible and dashboard_private.registration_observation_teacher_subject_matches_v1(i.subject,t.subjects))
       or not exists(select 1 from public.classroom_catalogs c where c.id=s.classroom_catalog_id and c.is_visible and (cardinality(c.subjects)=0 or i.subject=any(c.subjects))) then
       code:='missing_resource'; label:='사용 가능한 선생님·강의실을 선택하세요.';
     elsif not coalesce((ref->>'complete')::boolean,false)
       or exists(select 1 from public.timetable_plan_slots x where x.item_id=any(selected) and x.id<>s.id and x.weekday=s.weekday and x.start_minute<s.end_minute and x.end_minute>s.start_minute and (x.item_id=s.item_id or x.teacher_catalog_id=s.teacher_catalog_id or x.classroom_catalog_id=s.classroom_catalog_id))
       or exists(select 1 from public.timetable_plan_slots x join public.timetable_plan_items xi on xi.id=x.item_id where x.plan_id=target_id and xi.state='draft' and x.weekday=s.weekday and x.start_minute<s.end_minute and x.end_minute>s.start_minute and (x.teacher_catalog_id=s.teacher_catalog_id or x.classroom_catalog_id=s.classroom_catalog_id))
       or exists(select 1 from jsonb_array_elements(ref->'shadowSlots') x where (x->>'weekday')::int=s.weekday and (x->>'startMinute')::int<s.end_minute and (x->>'endMinute')::int>s.start_minute and ((x->>'teacherId')::uuid=s.teacher_catalog_id or (x->>'classroomId')::uuid=s.classroom_catalog_id))
       or (period_from is not null and exists(select 1 from jsonb_array_elements(ref->'datedUnresolvedOccupancies') x where x->>'date' is null or (x->>'date')::date between period_from and period_to))
       or (period_from is not null and exists(select 1 from jsonb_array_elements(ref->'datedSessions') x where x->>'state' in('active','exception','makeup') and (x->>'date')::date between period_from and period_to and extract(dow from (x->>'date')::date)::int=s.weekday and (x->>'startMinute')::int<s.end_minute and (x->>'endMinute')::int>s.start_minute and ((x->>'teacherId')::uuid=s.teacher_catalog_id or (x->>'classroomId')::uuid=s.classroom_catalog_id))) then
       code:='conflict'; label:='선택한 수업 또는 목적지 시간표와 겹칩니다.';
     end if;
     if code is not null then
       entry:=jsonb_build_object('sourceId',i.id,'code',code,'label',label,'relatedIds',jsonb_build_array(s.id));
       if keep_pending then warnings:=warnings||jsonb_build_array(entry); pending_ids:=pending_ids||jsonb_build_array(s.id);
       else blockers:=blockers||jsonb_build_array(entry); end if;
     end if;
   end loop;
   if keep_pending and jsonb_array_length(i.pending_slots)+(select count(*) from public.timetable_plan_slots where item_id=i.id and pending_ids ? id::text)>2000 then
     raise exception using errcode='22023',message='timetable_capacity';
   end if;
 end loop;
 if target_id is not null and (target_snapshot#>>'{capacity,slotCount}')::int+(select count(*) from public.timetable_plan_slots where item_id=any(selected) and not pending_ids ? id::text)>2000 then
   raise exception using errcode='22023',message='timetable_capacity'; end if;
 return jsonb_build_object('request',r,'fingerprint',md5(jsonb_build_object('request',r,'source',source_snapshot,'target',target_snapshot,'reference',ref,'actor',auth.uid(),'role',dashboard_private.timetable_actor_role_v1(),'subjectAreas',(select jsonb_agg(to_jsonb(a) order by a.subject,a.area_key) from public.academic_subject_areas a))::text),
   'shadowFingerprint',ref->>'shadowFingerprint','mappings',mappings,'blockers',blockers,'warnings',warnings,'pendingSlotIds',pending_ids);
end $function$

CREATE OR REPLACE FUNCTION dashboard_private.prepare_timetable_transfer_v1(r jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source_id uuid; target_id uuid;
begin
 if jsonb_typeof(r) is distinct from 'object'
   or exists(select 1 from jsonb_object_keys(r) k where k not in('source','target','mode','itemIds','onConflict'))
   or jsonb_typeof(r->'source') is distinct from 'object'
   or jsonb_typeof(r->'target') is distinct from 'object'
   or r#>>'{source,kind}' is distinct from 'plan'
   or coalesce(r#>>'{target,kind}','') not in('plan','operational')
   or coalesce(r->>'mode','') not in('copy','move')
   or coalesce(r->>'onConflict','') not in('reject','keep_pending')
   or jsonb_typeof(r->'itemIds') is distinct from 'array'
 then raise exception using errcode='22023',message='timetable_invalid'; end if;
 if exists(select 1 from jsonb_object_keys(r->'source') k where k not in('kind','planId'))
   or exists(select 1 from jsonb_object_keys(r->'target') k where k not in('kind','planId'))
   or jsonb_array_length(r->'itemIds') not between 1 and 500
   or (r->>'onConflict'='keep_pending' and (r->>'mode'<>'copy' or r#>>'{target,kind}'<>'plan'))
 then raise exception using errcode='22023',message='timetable_invalid'; end if;
 source_id:=(r#>>'{source,planId}')::uuid;
 target_id:=(r#>>'{target,planId}')::uuid;
 if source_id is null or (r#>>'{target,kind}'='plan' and (target_id is null or target_id=source_id))
   or (r#>>'{target,kind}'='operational' and r->'target' ? 'planId')
   or exists(select 1 from jsonb_array_elements(r->'itemIds') x where jsonb_typeof(x)<>'string' or (x#>>'{}')::uuid is null)
   or (select count(*)<>count(distinct (value#>>'{}')::uuid) from jsonb_array_elements(r->'itemIds'))
 then raise exception using errcode='22023',message='timetable_invalid'; end if;
 perform dashboard_private.timetable_require_v1(source_id,true,target_id is null);
 if target_id is not null then perform dashboard_private.timetable_require_v1(target_id,true); end if;
 perform dashboard_private.lock_timetable_operating_resources_v1();
 perform id from public.timetable_plans where id in(source_id,target_id) order by id for update;
 -- Sharing/role changes that won the lock must be observed before receipts too.
 perform dashboard_private.timetable_require_v1(source_id,true,target_id is null);
 if target_id is not null then perform dashboard_private.timetable_require_v1(target_id,true); end if;
 if not exists(select 1 from public.timetable_plans where id=source_id)
   or (target_id is not null and not exists(select 1 from public.timetable_plans where id=target_id))
 then raise exception using errcode='22023',message='timetable_invalid'; end if;
 perform c.id from public.classes c where c.status='수강'
   or exists(select 1 from public.timetable_plan_items i where i.plan_id in(source_id,target_id) and c.id in(i.source_class_id,i.applied_class_id))
   or exists(select 1 from public.class_lesson_sessions s where s.class_id=c.id)
   order by c.id for update;
exception when invalid_text_representation or numeric_value_out_of_range then
 raise exception using errcode='22023',message='timetable_invalid';
end $function$

CREATE OR REPLACE FUNCTION dashboard_private.read_timetable_operating_reference_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb; dated jsonb:='[]'; blockers jsonb:='[]'; c record; v jsonb; tid uuid; rid uuid; dt date; a int; b int; state text; ident text; occupancy jsonb; raw jsonb:='[]'; legacy_raw jsonb[]:='{}'; legacy_dated jsonb[]:='{}'; legacy_blockers jsonb[]:='{}'; identity_counts jsonb;
begin
 r:=dashboard_private.read_timetable_weekly_reference_v1();
 -- Aggregate once, preserving exact lesson.id ordering and full dated history.
 -- Repeated JSONB concatenation copied growing arrays quadratically.
 select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'classId',s.class_id,'sourceSlotId',s.source_schedule_slot_id,'date',s.session_date,'state',s.schedule_state,'start',s.start_time,'end',s.end_time,'teacher',s.teacher_catalog_id,'room',s.classroom_catalog_id,'revision',s.revision) order by s.id),'[]'::jsonb),
        coalesce(jsonb_agg(jsonb_build_object('classId',s.class_id,'label',s.name,'scope','all','resourceId',null,'reason','incomplete_read','date',s.session_date,'sessionId',s.id,'occupancyFingerprint',md5(jsonb_build_array(s.class_id,s.source_schedule_slot_id,s.session_date,s.schedule_state,s.start_time,s.end_time,s.teacher_catalog_id,s.classroom_catalog_id)::text)) order by s.id) filter(where s.schedule_state in('active','exception','makeup') and (s.teacher_catalog_id is null or s.classroom_catalog_id is null or s.start_time is null or s.end_time is null or extract(second from s.start_time)<>0 or extract(second from s.end_time)<>0)),'[]'::jsonb),
        coalesce(jsonb_agg(jsonb_build_object('id','session:'||s.id::text,'classId',s.class_id,'sourceSlotId',s.source_schedule_slot_id,'date',s.session_date,'state',s.schedule_state,'startMinute',extract(epoch from s.start_time)::int/60,'endMinute',extract(epoch from s.end_time)::int/60,'teacherId',s.teacher_catalog_id,'classroomId',s.classroom_catalog_id,'revision',s.revision) order by s.id),'[]'::jsonb)
 into raw,blockers,dated
 from (select lesson.*,class_row.name from public.class_lesson_sessions lesson
       join public.classes class_row on class_row.id=lesson.class_id
       where class_row.schedule_storage_mode='normalized') s;
 for c in select id,name,schedule_plan from public.classes where schedule_storage_mode<>'normalized' order by id loop
 if c.schedule_plan ? 'sessions' and jsonb_typeof(c.schedule_plan->'sessions')<>'array' then
 legacy_blockers:=array_append(legacy_blockers,jsonb_build_object('classId',c.id,'label',c.name,'scope','all','resourceId',null,'reason','incomplete_read','date',null));continue;end if;
 -- Count legacy identities once per class; preserve the original COALESCE semantics.
 select coalesce(jsonb_object_agg(identity_key,n),'{}'::jsonb) into identity_counts
 from (select coalesce(x->>'id',x->>'sessionKey') identity_key,count(*) n
       from jsonb_array_elements(coalesce(c.schedule_plan->'sessions','[]')) x
       where coalesce(x->>'id',x->>'sessionKey') is not null group by 1) counts;
 for v in select value from jsonb_array_elements(coalesce(c.schedule_plan->'sessions','[]')) loop
 -- Scalar legacy entries are diagnostic data, never JSON-object operations.
 -- Content-only fields remain absent from an object's occupancy fingerprint.
 occupancy:=case when jsonb_typeof(v)='object' then v-array['memo','publicNote','teacherNote','textbook','textbooks','homework','content','lessonContent','learningContent','textbookEntries','progressStatus'] else v end;
 state:=coalesce(nullif(v->>'scheduleState',''),'active');
 if state in('skipped','tbd') then continue;end if;
 legacy_raw:=array_append(legacy_raw,jsonb_build_object('classId',c.id,'session',occupancy));
 -- Date knowledge is independent of time/resource validity and must survive it.
 dt:=null;
 begin dt:=(v->>'date')::date;
 exception when invalid_datetime_format or datetime_field_overflow then dt:=null;
 end;
 begin
 if jsonb_typeof(v)<>'object' then raise exception 'unresolved';end if;
 -- Validate the original text before casting: even sub-microsecond fractions
 -- must not be rounded into an apparently whole-minute reservation.
 if (v->>'startTime') !~ '^[0-9]{1,2}:[0-9]{2}(:00([.]0+)?)?$'
   or (v->>'endTime') !~ '^[0-9]{1,2}:[0-9]{2}(:00([.]0+)?)?$' then raise exception 'unresolved';end if;
 a:=extract(epoch from (v->>'startTime')::time)::int/60;b:=extract(epoch from (v->>'endTime')::time)::int/60;
 tid:=nullif(v->>'teacherCatalogId','')::uuid;rid:=nullif(v->>'classroomCatalogId','')::uuid;
 if tid is null then select min(id::text)::uuid into tid from public.teacher_catalogs where name=v->>'teacherName' having count(*)=1;end if;
 if rid is null then select min(id::text)::uuid into rid from public.classroom_catalogs where name=v->>'classroomName' having count(*)=1;end if;
 if dt is null or a is null or b is null or a>=b or tid is null or rid is null or state not in('active','exception','makeup') or not exists(select 1 from public.teacher_catalogs where id=tid) or not exists(select 1 from public.classroom_catalogs where id=rid) then raise exception 'unresolved';end if;
 ident:=coalesce(nullif(v->>'id',''),nullif(v->>'sessionKey',''));
 if ident is null or coalesce((identity_counts->>ident)::bigint,0)>1 then raise exception 'unresolved';end if;
 legacy_dated:=array_append(legacy_dated,jsonb_build_object('id','legacy-session:'||c.id::text||':'||ident,'classId',c.id,'sourceSlotId',null,'date',dt,'state',state,'startMinute',a,'endMinute',b,'teacherId',tid,'classroomId',rid,'revision',0));
 exception when others then
 legacy_blockers:=array_append(legacy_blockers,jsonb_build_object('classId',c.id,'label',c.name,'scope','all','resourceId',null,'reason','incomplete_read','date',dt,'occupancyFingerprint',md5(occupancy::text)));
 end;
 end loop;
 end loop;
 -- PL/pgSQL expanded arrays append without repeatedly copying the JSONB history.
 -- Materialize each legacy array once, after the normalized rows, in original order.
 raw:=raw||to_jsonb(legacy_raw);
 dated:=dated||to_jsonb(legacy_dated);
 blockers:=blockers||to_jsonb(legacy_blockers);
 return r||jsonb_build_object('asOfDate',(now() at time zone 'Asia/Seoul')::date,'datedSessions',dated,'datedUnresolvedOccupancies',blockers,'datedComplete',jsonb_array_length(blockers)=0,'datedFingerprint',md5((dated||blockers||raw)::text),'shadowFingerprint',md5((r->>'shadowFingerprint')||((now() at time zone 'Asia/Seoul')::date)::text||md5((dated||blockers||raw)::text)));
end $function$

CREATE OR REPLACE FUNCTION dashboard_private.read_timetable_weekly_reference_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c record; s record; piece text; parts text[]; days text; d text; tid uuid; rid uuid; startm int; endm int; sid uuid;
 slots jsonb:='[]'; blockers jsonb:='[]'; classes jsonb:='[]'; teachers jsonb; rooms jsonb; payload jsonb; count_parts int; invalid boolean; raw_state jsonb:='[]';
begin
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'isVisible',is_visible,'subjects',subjects) order by id),'[]') into teachers from public.teacher_catalogs;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'isVisible',is_visible,'subjects',subjects) order by id),'[]') into rooms from public.classroom_catalogs;
 for c in select id,name,subject,grade,status,schedule_revision,schedule_storage_mode,schedule,teacher,room from public.classes
 where dashboard_private.academic_class_status_v1(status,nullif(btrim(start_date),'')::date,nullif(btrim(end_date),'')::date)='수강' order by id loop
 classes:=classes||jsonb_build_array(jsonb_build_object('id',c.id,'name',c.name,'subject',c.subject,'grade',c.grade,'status','수강','revision',c.schedule_revision));
 raw_state:=raw_state||to_jsonb(c);
 count_parts:=0; invalid:=false;
 if c.schedule_storage_mode='normalized' then
 for s in select * from public.class_schedule_slots where class_id=c.id order by id loop
 count_parts:=count_parts+1;
 raw_state:=raw_state||jsonb_build_object('normalizedSlot',to_jsonb(s));
 if s.teacher_catalog_id is null or s.classroom_catalog_id is null or extract(second from s.start_time)<>0 or extract(second from s.end_time)<>0 then invalid:=true; continue; end if;
 slots:=slots||jsonb_build_array(jsonb_build_object('id','live:'||c.id::text||':'||s.id::text,'sourceSlotId',s.id,'classId',c.id,'weekday',s.weekday,'startMinute',extract(epoch from s.start_time)::int/60,'endMinute',extract(epoch from s.end_time)::int/60,'teacherId',s.teacher_catalog_id,'classroomId',s.classroom_catalog_id,'classRevision',c.schedule_revision));
 end loop;
 else
 -- Strict complete tokens only. Multi-resource legacy strings remain blocked
 -- unless each whole schedule line can resolve its exact catalog labels.
 for piece in select btrim(x) from regexp_split_to_table(coalesce(c.schedule,''), E'[\\n;]+|,[[:space:]]*(?=[월화수목금토일][월화수목금토일 /,]*[[:space:]]+[0-9])') x loop
 parts:=regexp_match(piece,'^([월화수목금토일][월화수목금토일 /,]*)[[:space:]]+([0-9]{1,2}:[0-9]{2})[[:space:]]*[-~][[:space:]]*([0-9]{1,2}:[0-9]{2})([[:space:]]*[(]([^,()]+),[[:space:]]*([^()]+)[)])?$');
 if parts is null then invalid:=true; continue; end if;
 select min(id::text)::uuid into tid from public.teacher_catalogs where name=btrim(coalesce(parts[5],c.teacher)) having count(*)=1;
 select min(id::text)::uuid into rid from public.classroom_catalogs where name=btrim(coalesce(parts[6],c.room)) having count(*)=1;
 if tid is null or rid is null then invalid:=true; continue; end if;
 startm:=split_part(parts[2],':',1)::int*60+split_part(parts[2],':',2)::int;
 endm:=split_part(parts[3],':',1)::int*60+split_part(parts[3],':',2)::int;
 if split_part(parts[2],':',2)::int>59 or split_part(parts[3],':',2)::int>59 or startm<0 or startm>=endm or endm>1440 then invalid:=true;continue;end if;
 days:=regexp_replace(parts[1],'[ /,]','','g');
 for d in select regexp_split_to_table(days,'') loop
 count_parts:=count_parts+1;
 sid:=md5(c.id::text||':'||piece||':'||d)::uuid;
 slots:=slots||jsonb_build_array(jsonb_build_object('id','live:'||c.id::text||':'||sid::text,'sourceSlotId',null,'classId',c.id,'weekday',strpos('일월화수목금토',d)-1,'startMinute',startm,'endMinute',endm,'teacherId',tid,'classroomId',rid,'classRevision',c.schedule_revision));
 end loop;
 end loop;
 end if;
 if invalid or count_parts=0 then blockers:=blockers||jsonb_build_array(jsonb_build_object('classId',c.id,'label',c.name,'scope','all','resourceId',null,'reason','incomplete_read','occupancyFingerprint',md5(((to_jsonb(c)-array['name','subject','grade','schedule_revision'])||jsonb_build_object('slots',(select coalesce(jsonb_agg(jsonb_build_array(z.id,z.weekday,z.start_time,z.end_time,z.teacher_catalog_id,z.classroom_catalog_id) order by z.id),'[]') from public.class_schedule_slots z where z.class_id=c.id)))::text))); end if;
 end loop;
 payload:=jsonb_build_object('shadowSlots',slots,'shadowClasses',classes,'catalogs',jsonb_build_object('teachers',teachers,'classrooms',rooms),'unresolvedOccupancies',blockers,'complete',jsonb_array_length(blockers)=0);
 return payload||jsonb_build_object('shadowFingerprint',md5((payload||jsonb_build_object('source',raw_state))::text));
end $function$

CREATE OR REPLACE FUNCTION dashboard_private.timetable_import_source_v1(src jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.classes; pref public.app_preferences; entry jsonb; line jsonb; lines jsonb; entries jsonb:='[]'; raw jsonb:='[]'; safe jsonb; sid uuid; piece text; parts text[]; day text; selected uuid[]; detail text; resources text[]; teacher_text text; room_text text;
begin
 if jsonb_typeof(src) is distinct from 'object' or coalesce(src->>'kind','') not in('preparation','legacy') then raise exception using errcode='22023',message='timetable_invalid'; end if;
 if src->>'kind'='legacy' then
   if exists(select 1 from jsonb_object_keys(src) k where k not in('kind','key')) or src->>'key' not like 'planner:term:%' then raise exception using errcode='22023',message='timetable_invalid'; end if;
   select * into pref from public.app_preferences where key=src->>'key';
   if not found or jsonb_typeof(pref.value->'entries') is distinct from 'object' then raise exception using errcode='22023',message='timetable_invalid'; end if;
   raw:=jsonb_build_object('key',pref.key,'updatedAt',pref.updated_at,'value',pref.value);
   for entry in select value from jsonb_each(pref.value->'entries') order by key loop
     lines:='[]'; sid:=null;
     -- Never project arbitrary old keys, raw entries or student/status fields.
     if jsonb_typeof(entry->'scheduleLines')='array' then
       for line in select value from jsonb_array_elements(entry->'scheduleLines') loop
         lines:=lines||jsonb_build_array(jsonb_build_object('day',dashboard_private.timetable_import_text_v1(line->'day'),'start',dashboard_private.timetable_import_text_v1(line->'start'),'end',dashboard_private.timetable_import_text_v1(line->'end'),
           'teacher',coalesce(nullif(dashboard_private.timetable_import_text_v1(line->'teacher'),''),dashboard_private.timetable_import_text_v1(entry->'teacher')),
           'classroom',coalesce(nullif(dashboard_private.timetable_import_text_v1(line->'classroom'),''),dashboard_private.timetable_import_text_v1(entry->'classroom'))));
       end loop;
     elsif entry ? 'scheduleLines' then lines:=jsonb_build_array(jsonb_build_object('day','','start','','end','','teacher','','classroom','')); end if;
     begin select id into sid from public.classes where id=(entry->>'classId')::uuid; exception when invalid_text_representation then sid:=null; end;
     if nullif(btrim(dashboard_private.timetable_import_text_v1(entry->'subject')),'') is null then raise exception using errcode='22023',message='timetable_import_metadata_missing'; end if;
     safe:=jsonb_build_object('name',coalesce(nullif(left(dashboard_private.timetable_import_text_v1(entry->'className'),200),''),'복구 수업'),
       'subject',left(dashboard_private.timetable_import_text_v1(entry->'subject'),80),'grade','','capacity',null,'tuition',null,'subjectAreaKey',null,
       'sourceClassId',sid,'scheduleLines',lines);
     entries:=entries||jsonb_build_array(safe);
   end loop;
 else
   if exists(select 1 from jsonb_object_keys(src) k where k not in('kind','classIds')) or jsonb_typeof(src->'classIds') is distinct from 'array' then raise exception using errcode='22023',message='timetable_invalid'; end if;
   select array_agg(value::uuid order by value::uuid) into selected from jsonb_array_elements_text(src->'classIds');
   if coalesce(cardinality(selected),0) not between 1 and 500 or cardinality(selected)<>(select count(distinct x) from unnest(selected) x)
      or (select count(*) from public.classes where id=any(selected) and status='개강 준비')<>cardinality(selected) then raise exception using errcode='22023',message='timetable_invalid'; end if;
   for c in select * from public.classes where id=any(selected) order by id loop
     lines:='[]';
     if c.schedule_storage_mode='normalized' then
       select coalesce(jsonb_agg(jsonb_build_object('day',substring('일월화수목금토' from s.weekday+1 for 1),'start',s.start_time::text,'end',s.end_time::text,'teacher',s.teacher_name,'classroom',s.classroom_name,'teacherId',s.teacher_catalog_id,'classroomId',s.classroom_catalog_id,'sourceSlotId',s.id) order by s.id),'[]') into lines from public.class_schedule_slots s where s.class_id=c.id;
     else
       for piece in select btrim(x) from regexp_split_to_table(coalesce(c.schedule,''), E'[\n;]+|,[[:space:]]*(?=[월화수목금토일][월화수목금토일 /,]*[[:space:]]+[0-9])') x where btrim(x)<>'' loop
         parts:=regexp_match(piece,'^([월화수목금토일][월화수목금토일 /,]*)[[:space:]]+([0-9]{1,2}:[0-9]{2})[[:space:]]*[-~–][[:space:]]*([0-9]{1,2}:[0-9]{2})([[:space:]]*[(]([^()]*)[)])?$');
         if parts is null then
           -- Keep only the schedule string and known placement fields, never a raw row.
           lines:=lines||jsonb_build_array(jsonb_build_object('day',coalesce(substring(piece from '^([월화수목금토일])'),''),'start','','end','','teacher',c.teacher,'classroom',c.room,'originalSchedule',left(piece,2000)));
         else
           detail:=btrim(coalesce(parts[5],'')); teacher_text:=coalesce(c.teacher,''); room_text:=coalesce(c.room,'');
           if detail ~ '[,，/]' then
             resources:=regexp_split_to_array(detail,'[,，/]');
             teacher_text:=btrim(resources[1]); room_text:=btrim(array_to_string(resources[2:cardinality(resources)],', '));
           elsif detail<>'' then
             if detail ~ '(본관|별관|강의실|교실|본[0-9]|별[0-9]|강$|실$)' then room_text:=detail;
             else teacher_text:=detail; end if;
           end if;
           for day in select regexp_split_to_table(regexp_replace(parts[1],'[ /,]','','g'),'') loop
             lines:=lines||jsonb_build_array(jsonb_build_object('day',day,'start',parts[2],'end',parts[3],'teacher',teacher_text,'classroom',room_text,'originalSchedule',left(piece,2000)));
           end loop;
         end if;
       end loop;
     end if;
     safe:=jsonb_build_object('name',c.name,'subject',c.subject,'grade',coalesce(c.grade,''),'capacity',c.capacity,'tuition',c.fee,'subjectAreaKey',c.subject_area_key,'sourceClassId',c.id,'scheduleLines',lines);
     entries:=entries||jsonb_build_array(safe); raw:=raw||jsonb_build_array(safe||jsonb_build_object('scheduleRevision',c.schedule_revision,'schedule',c.schedule,'mode',c.schedule_storage_mode));
   end loop;
 end if;
 if jsonb_array_length(entries) not between 1 and 500 or exists(select 1 from jsonb_array_elements(entries) x where jsonb_array_length(x->'scheduleLines')>2000) then raise exception using errcode='22023',message='timetable_capacity'; end if;
 return jsonb_build_object('source',src,'sourceFingerprint',md5(raw::text),'entries',entries);
exception when invalid_text_representation or numeric_value_out_of_range then raise exception using errcode='22023',message='timetable_invalid';
end $function$

CREATE OR REPLACE FUNCTION dashboard_private.timetable_operating_finalize_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare oldref jsonb; r jsonb;
begin
 select reference into oldref from dashboard_private.timetable_operating_write_baselines where transaction_id=new.transaction_id;
 if oldref is null then return null;end if;
 perform dashboard_private.assert_timetable_operational_conflicts_v1();
 r:=dashboard_private.read_timetable_operating_reference_v1();
 if oldref->>'shadowFingerprint' is distinct from r->>'shadowFingerprint' then
 update public.timetable_invalidation_signals set change_sequence=change_sequence+1,updated_at=clock_timestamp() where id='operating';
 end if;
 delete from dashboard_private.timetable_operating_write_baselines where transaction_id=new.transaction_id;
 return null;
end $function$

CREATE OR REPLACE FUNCTION dashboard_private.timetable_receipt_v1(p_operation text, p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare r dashboard_private.timetable_plan_mutation_receipts;
begin
 if jsonb_typeof(p_command)<>'object' or nullif(btrim(p_command->>'requestKey'),'') is null or length(p_command->>'requestKey')>200 then raise exception using errcode='22023',message='timetable_invalid';end if;
 select * into r from dashboard_private.timetable_plan_mutation_receipts where actor_id=auth.uid() and operation=p_operation and request_key=p_command->>'requestKey';
 if found then
 if r.request_hash<>md5(p_command::text) then raise exception using errcode='22023',message='timetable_invalid';end if;
 return r.response;
 end if; return null;
end $function$

CREATE OR REPLACE FUNCTION dashboard_private.validate_timetable_item_slots_v1(p_plan uuid, p_item uuid, p_subject text, p_slots jsonb, p_reference jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v jsonb; other jsonb; old public.timetable_plan_slots; changed boolean; tid uuid; rid uuid; sid uuid; day int; a int; b int; target_from date; target_to date; dt date;
begin
 select target_start_date,target_end_date into target_from,target_to from public.timetable_plans where id=p_plan;
 if jsonb_typeof(p_slots) is distinct from 'array' then raise exception using errcode='22023',message='timetable_invalid';end if;
 if jsonb_array_length(p_slots)>2000 then raise exception using errcode='22023',message='timetable_capacity';end if;
 if (select count(*)<>count(distinct (x->>'id')::uuid) from jsonb_array_elements(p_slots) x) then raise exception using errcode='22023',message='timetable_invalid';end if;
 for v in select value from jsonb_array_elements(p_slots) loop
 if jsonb_typeof(v)<>'object' or exists(select 1 from jsonb_object_keys(v) k where k not in('id','itemId','planId','weekday','startMinute','endMinute','teacherId','classroomId','sourceSlotId','teacherName','classroomName')) then raise exception using errcode='22023',message='timetable_invalid';end if;
 sid:=(v->>'id')::uuid;tid:=(v->>'teacherId')::uuid;rid:=(v->>'classroomId')::uuid;day:=(v->>'weekday')::int;a:=(v->>'startMinute')::int;b:=(v->>'endMinute')::int;
 if sid is null or tid is null or rid is null or (v->>'planId')::uuid is distinct from p_plan or (v->>'itemId')::uuid is distinct from p_item or day is null or day not between 0 and 6 or a is null or b is null or a<0 or b>1440 or a>=b then raise exception using errcode='22023',message='timetable_invalid';end if;
 select * into old from public.timetable_plan_slots where id=sid;
 if found and (old.plan_id<>p_plan or old.item_id<>p_item) then raise exception using errcode='22023',message='timetable_invalid';end if;
 if (v->>'sourceSlotId')::uuid is distinct from old.source_slot_id then raise exception using errcode='22023',message='timetable_invalid';end if;
 changed:=old.id is null or (old.weekday,old.start_minute,old.end_minute,old.teacher_catalog_id,old.classroom_catalog_id) is distinct from (day,a,b,tid,rid);
 if not changed then continue;end if;
 if not exists(select 1 from public.teacher_catalogs where id=tid and is_visible and dashboard_private.registration_observation_teacher_subject_matches_v1(p_subject,subjects)) or not exists(select 1 from public.classroom_catalogs where id=rid and is_visible and (cardinality(subjects)=0 or p_subject=any(subjects))) then raise exception using errcode='22023',message='timetable_invalid';end if;
 if not coalesce((p_reference->>'complete')::boolean,false) then raise exception using errcode='23P01',message='timetable_resource_conflict';end if;
 if exists(select 1 from jsonb_array_elements(p_slots) x where (x->>'id')::uuid<>sid and (x->>'weekday')::int=day and (x->>'startMinute')::int<b and (x->>'endMinute')::int>a) then raise exception using errcode='23P01',message='timetable_resource_conflict';end if;
 if exists(select 1 from public.timetable_plan_slots s join public.timetable_plan_items i on i.id=s.item_id where s.plan_id=p_plan and s.item_id<>p_item and i.state='draft' and s.weekday=day and s.start_minute<b and s.end_minute>a and (s.teacher_catalog_id=tid or s.classroom_catalog_id=rid)) then raise exception using errcode='23P01',message='timetable_resource_conflict';end if;
 if exists(select 1 from jsonb_array_elements(p_reference->'shadowSlots') x where (x->>'weekday')::int=day and (x->>'startMinute')::int<b and (x->>'endMinute')::int>a and ((x->>'teacherId')::uuid=tid or (x->>'classroomId')::uuid=rid)) then raise exception using errcode='23P01',message='timetable_resource_conflict';end if;
 if target_from is not null and target_to is not null then
 if exists(select 1 from jsonb_array_elements(p_reference->'datedUnresolvedOccupancies') z where z->>'date' is null or (z->>'date')::date between target_from and target_to) then raise exception using errcode='23P01',message='timetable_resource_conflict';end if;
 for dt in select distinct (value->>'date')::date from jsonb_array_elements(p_reference->'datedSessions') where (value->>'date')::date between target_from and target_to loop
 if extract(dow from dt)::int=day and exists(select 1 from jsonb_array_elements(p_reference->'datedSessions') x where x->>'state' in('active','exception','makeup') and (x->>'date')::date=dt and (x->>'startMinute')::int<b and (x->>'endMinute')::int>a and ((x->>'teacherId')::uuid=tid or (x->>'classroomId')::uuid=rid)) then raise exception using errcode='23P01',message='timetable_resource_conflict';end if;
 end loop;
 end if;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION public.close_class_atomic_v1(p_class_id uuid, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor_id uuid;
  v_operation constant text := 'close_class_atomic_v1';
  v_request_hash text;
  v_replay jsonb;
  v_response jsonb;
  v_class public.classes%rowtype;
  v_pre_status text;
  v_pre_class_students jsonb;
  v_pre_class_waitlists jsonb;
  v_pre_claims jsonb;
  v_current_claims jsonb;
  v_enrolled_student_ids uuid[] := '{}'::uuid[];
  v_waitlist_student_ids uuid[] := '{}'::uuid[];
  v_member_student_ids uuid[] := '{}'::uuid[];
  v_lock_student_ids uuid[] := '{}'::uuid[];
  v_parent_task_ids uuid[] := '{}'::uuid[];
  v_track_ids uuid[] := '{}'::uuid[];
  v_batch_ids uuid[] := '{}'::uuid[];
  v_recomputed_parent_ids uuid[] := '{}'::uuid[];
  v_released_enrollment_ids uuid[] := '{}'::uuid[];
  v_canceled_waitlist_ids uuid[] := '{}'::uuid[];
  v_student_id uuid;
  v_parent_id uuid;
  v_mode text;
  v_claim public.ops_registration_enrollments%rowtype;
  v_track public.ops_registration_subject_tracks%rowtype;
  v_claim_found boolean;
  v_student_count integer;
  v_closed_at timestamptz;
  v_previous_class_close_context text := coalesce(
    pg_catalog.current_setting('app.class_close_mutation', true),
    ''
  );
begin
  perform dashboard_private.lock_timetable_operating_resources_v1();
  v_actor_id := dashboard_private.assert_continuous_class_schedule_actor_v1(false);
  if p_class_id is null or p_request_key is null then
    raise exception 'class_close_input_invalid' using errcode = '22023';
  end if;

  v_request_hash := dashboard_private.continuous_class_schedule_hash_v1(
    pg_catalog.jsonb_build_object('classId', p_class_id)
  );
  v_replay := dashboard_private.continuous_class_schedule_request_replay_v1(
    v_operation,
    p_request_key,
    v_request_hash
  );
  if v_replay is not null then
    declare timetable_result jsonb; begin timetable_result := v_replay; perform dashboard_private.assert_timetable_operational_conflicts_v1(); return timetable_result; end;
  end if;

  select class_row.*
  into v_class
  from public.classes class_row
  where class_row.id = p_class_id;
  if not found then
    raise exception 'class_close_not_found' using errcode = 'P0002';
  end if;

  v_pre_status := v_class.status;
  v_pre_class_students := coalesce(v_class.student_ids, '[]'::jsonb);
  v_pre_class_waitlists := coalesce(v_class.waitlist_ids, '[]'::jsonb);
  if pg_catalog.jsonb_typeof(v_pre_class_students) <> 'array'
    or pg_catalog.jsonb_typeof(v_pre_class_waitlists) <> 'array'
  then
    raise exception 'class_close_roster_invalid' using errcode = '23514';
  end if;
  if exists (
    select 1
    from (
      select element.value
      from pg_catalog.jsonb_array_elements(v_pre_class_students) element(value)
      union all
      select element.value
      from pg_catalog.jsonb_array_elements(v_pre_class_waitlists) element(value)
    ) roster_element
    where pg_catalog.jsonb_typeof(roster_element.value) <> 'string'
      or (roster_element.value #>> '{}') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) then
    raise exception 'class_close_roster_invalid' using errcode = '23514';
  end if;

  select coalesce(
    pg_catalog.array_agg(roster_id order by roster_id),
    '{}'::uuid[]
  )
  into v_enrolled_student_ids
  from (
    select (element.value #>> '{}')::uuid as roster_id
    from pg_catalog.jsonb_array_elements(v_pre_class_students) element(value)
  ) roster;
  select coalesce(
    pg_catalog.array_agg(roster_id order by roster_id),
    '{}'::uuid[]
  )
  into v_waitlist_student_ids
  from (
    select (element.value #>> '{}')::uuid as roster_id
    from pg_catalog.jsonb_array_elements(v_pre_class_waitlists) element(value)
  ) roster;

  if pg_catalog.cardinality(v_enrolled_student_ids)
      <> pg_catalog.cardinality(
        array(select distinct member_id from pg_catalog.unnest(v_enrolled_student_ids) member_id)
      )
    or pg_catalog.cardinality(v_waitlist_student_ids)
      <> pg_catalog.cardinality(
        array(select distinct member_id from pg_catalog.unnest(v_waitlist_student_ids) member_id)
      )
    or exists (
      select 1
      from pg_catalog.unnest(v_enrolled_student_ids) enrolled_id
      where enrolled_id = any(v_waitlist_student_ids)
    )
  then
    raise exception 'class_close_roster_invalid' using errcode = '23514';
  end if;

  select coalesce(
    pg_catalog.array_agg(member_id order by member_id),
    '{}'::uuid[]
  )
  into v_member_student_ids
  from (
    select member_id from pg_catalog.unnest(v_enrolled_student_ids) member_id
    union
    select member_id from pg_catalog.unnest(v_waitlist_student_ids) member_id
  ) members;

  select coalesce(
    pg_catalog.jsonb_agg(pg_catalog.to_jsonb(enrollment) order by enrollment.id),
    '[]'::jsonb
  )
  into v_pre_claims
  from public.ops_registration_enrollments enrollment
  where enrollment.class_id = p_class_id;

  select coalesce(
    pg_catalog.array_agg(distinct track.task_id order by track.task_id),
    '{}'::uuid[]
  ), coalesce(
    pg_catalog.array_agg(distinct enrollment.track_id order by enrollment.track_id),
    '{}'::uuid[]
  ), coalesce(
    pg_catalog.array_agg(distinct enrollment.admission_batch_id order by enrollment.admission_batch_id)
      filter (where enrollment.admission_batch_id is not null),
    '{}'::uuid[]
  )
  into v_parent_task_ids, v_track_ids, v_batch_ids
  from public.ops_registration_enrollments enrollment
  join public.ops_registration_subject_tracks track on track.id = enrollment.track_id
  where enrollment.class_id = p_class_id;

  select coalesce(
    pg_catalog.array_agg(student_id order by student_id),
    '{}'::uuid[]
  )
  into v_lock_student_ids
  from (
    select member_id as student_id
    from pg_catalog.unnest(v_member_student_ids) member_id
    union
    select enrollment.student_id
    from public.ops_registration_enrollments enrollment
    where enrollment.class_id = p_class_id
      and enrollment.roster_active
      and enrollment.student_id is not null
    union
    select student.id
    from public.students student
    where coalesce(student.class_ids, '[]'::jsonb) ? p_class_id::text
      or coalesce(student.waitlist_class_ids, '[]'::jsonb) ? p_class_id::text
  ) students_to_lock;

  perform 1
  from public.ops_tasks task
  where task.id = any(v_parent_task_ids)
  order by task.id
  for update;
  perform 1
  from public.ops_registration_subject_tracks track
  where track.id = any(v_track_ids)
  order by track.id
  for update;
  perform 1
  from public.students student
  where student.id = any(v_lock_student_ids)
  order by student.id
  for update;
  perform 1
  from public.ops_registration_admission_batches batch
  where batch.id = any(v_batch_ids)
  order by batch.id
  for update;
  perform 1
  from public.ops_registration_enrollments enrollment
  where enrollment.class_id = p_class_id
  order by enrollment.id
  for update;

  select class_row.*
  into v_class
  from public.classes class_row
  where class_row.id = p_class_id
  for update;
  if not found then
    raise exception 'class_close_not_found' using errcode = 'P0002';
  end if;
  select coalesce(
    pg_catalog.jsonb_agg(pg_catalog.to_jsonb(enrollment) order by enrollment.id),
    '[]'::jsonb
  )
  into v_current_claims
  from public.ops_registration_enrollments enrollment
  where enrollment.class_id = p_class_id;

  if v_class.status is distinct from v_pre_status
    or coalesce(v_class.student_ids, '[]'::jsonb) is distinct from v_pre_class_students
    or coalesce(v_class.waitlist_ids, '[]'::jsonb) is distinct from v_pre_class_waitlists
    or v_current_claims is distinct from v_pre_claims
  then
    raise exception 'class_close_refresh_required' using errcode = '23514';
  end if;
  if exists (
    select 1
    from public.students student
    where (
      coalesce(student.class_ids, '[]'::jsonb) ? p_class_id::text
      or coalesce(student.waitlist_class_ids, '[]'::jsonb) ? p_class_id::text
    )
      and not (student.id = any(v_member_student_ids))
  ) then
    raise exception 'class_close_roster_invalid' using errcode = '23514';
  end if;
  if v_class.closed_at is not null or v_class.closed_by is not null then
    raise exception 'class_already_closed' using errcode = '23514';
  end if;
  if exists (
    select 1
    from public.ops_registration_enrollments enrollment
    left join public.ops_registration_admission_batches batch
      on batch.id = enrollment.admission_batch_id
    where enrollment.class_id = p_class_id
      and (
        enrollment.status = 'planned'
        or (
          enrollment.admission_batch_id is not null
          and batch.status not in ('completed', 'canceled')
        )
      )
  ) then
    raise exception 'class_close_open_admission_batch' using errcode = '23514';
  end if;

  select pg_catalog.count(*)::integer
  into v_student_count
  from public.students student
  where student.id = any(v_member_student_ids);
  if v_student_count <> pg_catalog.cardinality(v_member_student_ids)
    or exists (
      select 1
      from public.ops_registration_enrollments enrollment
      where enrollment.class_id = p_class_id
        and enrollment.roster_active
        and (
          enrollment.student_id is null
          or not (enrollment.student_id = any(v_member_student_ids))
        )
    )
  then
    raise exception 'class_close_roster_invalid' using errcode = '23514';
  end if;

  perform dashboard_private.with_continuous_class_schedule_audit_context_v1(
    p_class_id,
    p_request_key,
    v_operation,
    'class_closed'
  );
  perform pg_catalog.set_config('app.class_close_mutation', 'v1', true);

  foreach v_student_id in array v_member_student_ids
  loop
    v_mode := case
      when v_student_id = any(v_enrolled_student_ids) then 'enrolled'
      else 'waitlist'
    end;

    if not exists (
      select 1
      from public.students student
      where student.id = v_student_id
        and pg_catalog.jsonb_typeof(coalesce(student.class_ids, '[]'::jsonb)) = 'array'
        and pg_catalog.jsonb_typeof(coalesce(student.waitlist_class_ids, '[]'::jsonb)) = 'array'
        and (
          (
            v_mode = 'enrolled'
            and coalesce(student.class_ids, '[]'::jsonb) ? p_class_id::text
            and not (coalesce(student.waitlist_class_ids, '[]'::jsonb) ? p_class_id::text)
          )
          or (
            v_mode = 'waitlist'
            and coalesce(student.waitlist_class_ids, '[]'::jsonb) ? p_class_id::text
            and not (coalesce(student.class_ids, '[]'::jsonb) ? p_class_id::text)
          )
        )
    ) then
      raise exception 'class_close_roster_invalid' using errcode = '23514';
    end if;

    select enrollment.*
    into v_claim
    from public.ops_registration_enrollments enrollment
    where enrollment.class_id = p_class_id
      and enrollment.student_id = v_student_id
      and enrollment.roster_active;
    v_claim_found := found;
    if v_claim_found
      and (
        (v_mode = 'enrolled' and v_claim.status <> 'enrolled')
        or (v_mode = 'waitlist' and v_claim.status <> 'waitlisted')
      )
    then
      raise exception 'class_close_roster_invalid' using errcode = '23514';
    end if;

    perform dashboard_private.apply_student_class_roster_mode(
      v_student_id,
      p_class_id,
      'removed',
      v_mode,
      case when v_claim_found then v_claim.id else null end,
      'class_closed',
      v_actor_id
    );

    if v_claim_found and v_mode = 'enrolled' then
      update public.ops_registration_enrollments enrollment
      set
        status = 'enrolled',
        roster_active = false,
        roster_released_at = pg_catalog.now(),
        roster_release_reason = 'class_closed',
        roster_release_source_task_id = null,
        roster_release_kind = 'class_close',
        updated_at = pg_catalog.now()
      where enrollment.id = v_claim.id
        and enrollment.status = 'enrolled'
        and enrollment.roster_active;
      if not found then
        raise exception 'class_close_roster_invalid' using errcode = '23514';
      end if;
      v_released_enrollment_ids := pg_catalog.array_append(
        v_released_enrollment_ids,
        v_claim.id
      );
      select track.*
      into v_track
      from public.ops_registration_subject_tracks track
      where track.id = v_claim.track_id;
      perform dashboard_private.write_registration_track_event(
        v_track.task_id,
        v_track.id,
        'registration_enrollment_roster_released',
        v_track.pipeline_status,
        v_track.pipeline_status,
        'class_closed',
        pg_catalog.jsonb_build_object(
          'enrollmentId', v_claim.id,
          'sourceTaskId', null,
          'releaseKind', 'class_close',
          'enrollmentSnapshot', pg_catalog.jsonb_build_object(
            'id', v_claim.id,
            'classId', v_claim.class_id,
            'textbookId', v_claim.textbook_id,
            'admissionBatchId', v_claim.admission_batch_id,
            'classStartDate', v_claim.class_start_date,
            'classStartSessionKey', v_claim.class_start_session_key,
            'classStartSession', v_claim.class_start_session,
            'status', v_claim.status,
            'sortOrder', v_claim.sort_order
          )
        )
      );
      v_recomputed_parent_ids := pg_catalog.array_append(
        v_recomputed_parent_ids,
        v_track.task_id
      );
    elsif v_claim_found and v_mode = 'waitlist' then
      update public.ops_registration_enrollments enrollment
      set
        status = 'canceled',
        roster_active = false,
        roster_released_at = null,
        roster_release_reason = null,
        roster_release_source_task_id = null,
        roster_release_kind = null,
        updated_at = pg_catalog.now()
      where enrollment.id = v_claim.id
        and enrollment.status = 'waitlisted'
        and enrollment.roster_active;
      if not found then
        raise exception 'class_close_roster_invalid' using errcode = '23514';
      end if;
      v_canceled_waitlist_ids := pg_catalog.array_append(
        v_canceled_waitlist_ids,
        v_claim.id
      );
      select track.*
      into v_track
      from public.ops_registration_subject_tracks track
      where track.id = v_claim.track_id;
      if v_track.pipeline_status <> 'waiting'
        or v_track.waiting_kind <> 'current_class'
      then
        raise exception 'class_close_roster_invalid' using errcode = '23514';
      end if;
      perform dashboard_private.transition_registration_track_status(
        v_track.id,
        'not_registered',
        null,
        null,
        false
      );
      perform dashboard_private.write_registration_track_event(
        v_track.task_id,
        v_track.id,
        'registration_waitlist_canceled_by_class_close',
        'waiting',
        'not_registered',
        'class_closed',
        pg_catalog.jsonb_build_object(
          'enrollmentId', v_claim.id,
          'releaseKind', 'class_close'
        )
      );
      v_recomputed_parent_ids := pg_catalog.array_append(
        v_recomputed_parent_ids,
        v_track.task_id
      );
    end if;
  end loop;

  select class_row.*
  into v_class
  from public.classes class_row
  where class_row.id = p_class_id;
  if pg_catalog.jsonb_array_length(coalesce(v_class.student_ids, '[]'::jsonb)) <> 0
    or pg_catalog.jsonb_array_length(coalesce(v_class.waitlist_ids, '[]'::jsonb)) <> 0
  then
    raise exception 'class_close_roster_invalid' using errcode = '23514';
  end if;

  select coalesce(
    pg_catalog.array_agg(distinct parent_id order by parent_id),
    '{}'::uuid[]
  )
  into v_recomputed_parent_ids
  from pg_catalog.unnest(v_recomputed_parent_ids) parent_id;
  foreach v_parent_id in array v_recomputed_parent_ids
  loop
    perform dashboard_private.recompute_registration_parent(v_parent_id);
  end loop;

  v_closed_at := pg_catalog.now();
  update public.classes
  set
    status = '종강',
    closed_at = v_closed_at,
    closed_by = v_actor_id
  where id = p_class_id
    and closed_at is null
    and closed_by is null
  returning * into v_class;
  if not found then
    raise exception 'class_already_closed' using errcode = '23514';
  end if;
  perform pg_catalog.set_config(
    'app.class_close_mutation',
    v_previous_class_close_context,
    true
  );

  v_response := pg_catalog.jsonb_build_object(
    'id', p_class_id,
    'classId', p_class_id,
    'status', '종강',
    'closedAt', v_closed_at,
    'removedStudentCount', pg_catalog.cardinality(v_member_student_ids),
    'removedEnrolledCount', pg_catalog.cardinality(v_enrolled_student_ids),
    'removedWaitlistCount', pg_catalog.cardinality(v_waitlist_student_ids),
    'releasedEnrollmentIds', pg_catalog.to_jsonb(v_released_enrollment_ids),
    'canceledWaitlistEnrollmentIds', pg_catalog.to_jsonb(v_canceled_waitlist_ids)
  );
  declare timetable_result jsonb; begin timetable_result := dashboard_private.record_continuous_class_schedule_receipt_v1(
    v_operation,
    p_request_key,
    v_request_hash,
    v_response
  ); perform dashboard_private.assert_timetable_operational_conflicts_v1(); return timetable_result; end;
end;
$function$

CREATE OR REPLACE FUNCTION public.commit_timetable_plan_import_v1(p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare src jsonb:=p_command->'source'; preview jsonb; response jsonb; ref jsonb; entry jsonb; line jsonb; slot jsonb; candidate jsonb; kept jsonb; pending jsonb; reason text; a int; b int; d int; tid uuid; rid uuid; source_slot uuid; pid uuid:=gen_random_uuid(); iid uuid;
begin
 perform dashboard_private.timetable_require_v1(null,false,true);
 if jsonb_typeof(p_command) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_command) k where k not in('source','sourceFingerprint','name','requestKey')) or length(btrim(coalesce(p_command->>'name',''))) not between 1 and 120 then raise exception using errcode='22023',message='timetable_invalid'; end if;
 perform dashboard_private.lock_timetable_operating_resources_v1();
 perform dashboard_private.timetable_require_v1(null,false,true);
 response:=dashboard_private.timetable_receipt_v1('import',p_command); if response is not null then return response; end if;
 if src->>'kind'='preparation' then perform id from public.classes where id in(select value::uuid from jsonb_array_elements_text(src->'classIds')) order by id for update;
 elsif src->>'kind'='legacy' then perform key from public.app_preferences where key=src->>'key' for share; end if;
 preview:=dashboard_private.timetable_import_source_v1(src);
 if preview->>'sourceFingerprint' is distinct from p_command->>'sourceFingerprint' then raise exception using errcode='P0001',message='timetable_stale'; end if;
 ref:=dashboard_private.read_timetable_operating_reference_v1();
 insert into public.timetable_plans(id,name,created_by,updated_by) values(pid,btrim(p_command->>'name'),auth.uid(),auth.uid());
 for entry in select value from jsonb_array_elements(preview->'entries') loop
   iid:=gen_random_uuid(); kept:='[]'; pending:='[]';
   insert into public.timetable_plan_items(id,plan_id,name,subject,subject_area_key,grade,capacity,tuition,source_class_id)
   values(iid,pid,entry->>'name',entry->>'subject',entry->>'subjectAreaKey',entry->>'grade',(entry->>'capacity')::int,(entry->>'tuition')::int,(entry->>'sourceClassId')::uuid);
   for line in select value from jsonb_array_elements(entry->'scheduleLines') loop
     a:=null;b:=null;d:=null;tid:=null;rid:=null;source_slot:=null;reason:=null;
     if length(line->>'day')=1 and strpos('일월화수목금토',line->>'day')>0 then d:=strpos('일월화수목금토',line->>'day')-1; end if;
     if line->>'start' ~ '^[0-9]{1,2}:[0-5][0-9](:00)?$' and line->>'end' ~ '^[0-9]{1,2}:[0-5][0-9](:00)?$' then
       a:=split_part(line->>'start',':',1)::int*60+split_part(line->>'start',':',2)::int;
       b:=split_part(line->>'end',':',1)::int*60+split_part(line->>'end',':',2)::int;
     end if;
     if line ? 'teacherId' then tid:=(line->>'teacherId')::uuid; else select min(id::text)::uuid into tid from public.teacher_catalogs where name=line->>'teacher' having count(*)=1; end if;
     if line ? 'classroomId' then rid:=(line->>'classroomId')::uuid; else select min(id::text)::uuid into rid from public.classroom_catalogs where name=line->>'classroom' having count(*)=1; end if;
     source_slot:=(line->>'sourceSlotId')::uuid;
     if d is null or a is null or b is null or a<0 or a>=b or b>1440 then reason:='invalid_time';
     elsif tid is null or rid is null or not exists(select 1 from public.teacher_catalogs where id=tid and is_visible and dashboard_private.registration_observation_teacher_subject_matches_v1(entry->>'subject',subjects)) or not exists(select 1 from public.classroom_catalogs where id=rid and is_visible and (cardinality(subjects)=0 or entry->>'subject'=any(subjects))) then reason:='missing_resource'; end if;
     slot:=jsonb_build_object('id',gen_random_uuid(),'planId',pid,'itemId',iid,'weekday',d,'startMinute',a,'endMinute',b,'teacherId',tid,'classroomId',rid,'sourceSlotId',null);
     if reason is null then
       candidate:=kept||jsonb_build_array(slot);
       begin perform dashboard_private.validate_timetable_item_slots_v1(pid,iid,entry->>'subject',candidate,ref);
       exception when exclusion_violation then reason:='conflict'; end;
     end if;
     if reason is not null then
       pending:=pending||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'sourceText',line::text,'reason',reason,'weekday',d,'startMinute',a,'endMinute',b,'teacherId',tid,'classroomId',rid));
     else
       -- The normalized source ID is server-derived, never a client supplied ID.
       insert into public.timetable_plan_slots(id,plan_id,item_id,weekday,start_minute,end_minute,teacher_catalog_id,classroom_catalog_id,teacher_name,classroom_name,source_slot_id)
       values((slot->>'id')::uuid,pid,iid,d,a,b,tid,rid,(select name from public.teacher_catalogs where id=tid),(select name from public.classroom_catalogs where id=rid),source_slot);
       kept:=kept||jsonb_build_array(slot||jsonb_build_object('sourceSlotId',source_slot));
     end if;
   end loop;
   update public.timetable_plan_items set pending_slots=pending,default_teacher_id=(kept->0->>'teacherId')::uuid,default_classroom_id=(kept->0->>'classroomId')::uuid where id=iid;
 end loop;
 perform dashboard_private.timetable_check_capacity_v1(pid);
 update public.timetable_plans set change_sequence=1 where id=pid;
 response:=jsonb_build_object('plan',(public.get_timetable_plan_v1(pid))->'plan');
 perform dashboard_private.timetable_record_receipt_v1('import',p_command,response);
 return response;
exception when invalid_text_representation or numeric_value_out_of_range or check_violation or not_null_violation then raise exception using errcode='22023',message='timetable_invalid';
end $function$

CREATE OR REPLACE FUNCTION public.commit_timetable_plan_transfer_v1(p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb:=p_command->'request'; p jsonb; response jsonb; snapshot jsonb;
 source_id uuid; target_id uuid; transfer_id uuid:=gen_random_uuid(); target_item_id uuid; class_id uuid;
 selected uuid[]; i public.timetable_plan_items; s public.timetable_plan_slots; new_item public.timetable_plan_items; new_slot public.timetable_plan_slots; c public.classes;
 mappings jsonb:='[]'; applied jsonb:='[]'; removed jsonb:='[]'; created_items jsonb:='[]'; created_slots jsonb:='[]'; new_classes uuid[]:='{}'; slots jsonb; pending jsonb;
begin
 if jsonb_typeof(p_command) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_command) k where k not in('request','previewFingerprint','requestKey')) then
   raise exception using errcode='22023',message='timetable_invalid'; end if;
 perform dashboard_private.prepare_timetable_transfer_v1(r);
 -- Identical immutable receipt is returned before revisions, selection or preview
 -- revalidation. Authorization is always current, including on a replay.
 response:=dashboard_private.timetable_receipt_v1('transfer',p_command);
 if response is not null then return response; end if;
 p:=dashboard_private.evaluate_timetable_transfer_v1(r);
 if p->>'fingerprint' is distinct from p_command->>'previewFingerprint' then raise exception using errcode='P0001',message='timetable_stale'; end if;
 if jsonb_array_length(p->'blockers')>0 then raise exception using errcode='23P01',message='timetable_resource_conflict'; end if;
 source_id:=(r#>>'{source,planId}')::uuid; target_id:=(r#>>'{target,planId}')::uuid;
 select array_agg(value::uuid order by value::uuid) into selected from jsonb_array_elements_text(r->'itemIds');
 insert into dashboard_private.timetable_plan_transfers(id,request_key,actor_id,source_plan_id,target_plan_id,revisions)
 values(transfer_id,p_command->>'requestKey',auth.uid(),source_id,target_id,jsonb_build_object('previewFingerprint',p->>'fingerprint','request',r));
 for i in select * from public.timetable_plan_items where id=any(selected) order by id for update loop
   if target_id is null then
     -- Existing operating classes are never updated. Initialize only a freshly
     -- inserted preparing class before activating it in this same transaction.
     insert into public.classes(name,subject,subject_area_key,grade,capacity,fee,status)
       values(i.name,i.subject,i.subject_area_key,i.grade,i.capacity,i.tuition,'개강 준비') returning * into c;
     class_id:=c.id; new_classes:=array_append(new_classes,class_id);
     select jsonb_agg(jsonb_build_object('weekday',weekday,'startTime',lpad((start_minute/60)::text,2,'0')||':'||lpad((start_minute%60)::text,2,'0'),'endTime',lpad((end_minute/60)::text,2,'0')||':'||lpad((end_minute%60)::text,2,'0'),'teacherCatalogId',teacher_catalog_id,'classroomCatalogId',classroom_catalog_id,'sortOrder',0) order by id) into slots from public.timetable_plan_slots where item_id=i.id;
     perform public.initialize_new_class_schedule_v1(class_id,c.schedule_revision,dashboard_private.continuous_class_schedule_hash_v1(coalesce(c.schedule_plan,'{}'::jsonb)),slots,gen_random_uuid());
     update public.classes set status='수강' where id=class_id;
     mappings:=mappings||jsonb_build_array(jsonb_build_object('sourceId',i.id,'targetId',class_id,'targetClassId',class_id));
     if r->>'mode'='copy' then
       update public.timetable_plan_items set state='applied',applied_class_id=class_id,applied_transfer_id=transfer_id,applied_at=clock_timestamp(),revision=revision+1 where id=i.id returning * into new_item;
       applied:=applied||jsonb_build_array(dashboard_private.timetable_item_json_v1(new_item));
     end if;
   else
     target_item_id:=gen_random_uuid(); pending:=i.pending_slots;
     for s in select * from public.timetable_plan_slots where item_id=i.id and p->'pendingSlotIds' ? id::text order by id loop
       pending:=pending||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'sourceText',dashboard_private.timetable_slot_json_v1(s)::text,'reason',case when exists(select 1 from jsonb_array_elements(p->'warnings') w where w->>'code'='missing_resource' and w->'relatedIds' ? s.id::text) then 'missing_resource' else 'conflict' end,'weekday',s.weekday,'startMinute',s.start_minute,'endMinute',s.end_minute,'teacherId',s.teacher_catalog_id,'classroomId',s.classroom_catalog_id));
     end loop;
     insert into public.timetable_plan_items(id,plan_id,name,subject,subject_area_key,grade,capacity,tuition,default_teacher_id,default_classroom_id,duration_minutes,source_class_id,pending_slots)
       values(target_item_id,target_id,i.name,i.subject,i.subject_area_key,i.grade,i.capacity,i.tuition,i.default_teacher_id,i.default_classroom_id,i.duration_minutes,i.source_class_id,pending) returning * into new_item;
     created_items:=created_items||jsonb_build_array(dashboard_private.timetable_item_json_v1(new_item));
     for s in select * from public.timetable_plan_slots where item_id=i.id and not (p->'pendingSlotIds' ? id::text) order by id loop
       insert into public.timetable_plan_slots(plan_id,item_id,weekday,start_minute,end_minute,teacher_catalog_id,classroom_catalog_id,teacher_name,classroom_name,source_slot_id)
         values(target_id,target_item_id,s.weekday,s.start_minute,s.end_minute,s.teacher_catalog_id,s.classroom_catalog_id,s.teacher_name,s.classroom_name,s.source_slot_id) returning * into new_slot;
       created_slots:=created_slots||jsonb_build_array(dashboard_private.timetable_slot_json_v1(new_slot));
     end loop;
     mappings:=mappings||jsonb_build_array(jsonb_build_object('sourceId',i.id,'targetId',target_item_id,'targetClassId',null));
   end if;
   if r->>'mode'='move' then delete from public.timetable_plan_items where id=i.id; removed:=removed||jsonb_build_array(i.id); end if;
 end loop;
 if target_id is null or r->>'mode'='move' then
   update public.timetable_plans set change_sequence=change_sequence+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=source_id;
 end if;
 if target_id is not null then
   update public.timetable_plans set change_sequence=change_sequence+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=target_id;
   perform dashboard_private.timetable_check_capacity_v1(target_id);
 end if;
 perform dashboard_private.assert_timetable_operational_conflicts_v1();
 snapshot:=public.get_timetable_plan_v1(source_id);
 response:=jsonb_build_object('transferId',transfer_id,'shadowFingerprint',snapshot->>'shadowFingerprint','mappings',mappings,'appliedItems',applied,'removedItemIds',removed,'createdItems',created_items,'createdSlots',created_slots,
   'addedShadowSlots',coalesce((select jsonb_agg(x) from jsonb_array_elements(snapshot->'shadowSlots') x where (x->>'classId')::uuid=any(new_classes)),'[]'::jsonb),
   'addedShadowClasses',coalesce((select jsonb_agg(x) from jsonb_array_elements(snapshot->'shadowClasses') x where (x->>'id')::uuid=any(new_classes)),'[]'::jsonb),'snapshot',snapshot);
 update dashboard_private.timetable_plan_transfers set selected_mapping=mappings,result=response where id=transfer_id;
 perform dashboard_private.timetable_record_receipt_v1('transfer',p_command,response);
 return response;
exception when invalid_text_representation or numeric_value_out_of_range or check_violation or not_null_violation then
 raise exception using errcode='22023',message='timetable_invalid';
end $function$

CREATE OR REPLACE FUNCTION public.create_makeup_request_v2(p_input jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform dashboard_private.lock_timetable_operating_resources_v1();
  perform dashboard_private.assert_assistant_makeup_action_v1(null);
  declare timetable_result jsonb; begin timetable_result := dashboard_private.create_makeup_request_v2_unguarded(
    p_input,
    p_request_id
  ); perform dashboard_private.assert_timetable_operational_conflicts_v1(); return timetable_result; end;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_timetable_plan_revision_v1(p_plan_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r jsonb; p public.timetable_plans;
begin
 perform dashboard_private.timetable_require_v1(p_plan_id);
 select * into p from public.timetable_plans where id=p_plan_id;
 if not found then raise exception using errcode='22023',message='timetable_invalid';end if;
 r:=dashboard_private.read_timetable_operating_reference_v1();
 if p.target_start_date is not null and exists(select 1 from jsonb_array_elements(r->'datedUnresolvedOccupancies') b where b->>'date' is null or (b->>'date')::date between p.target_start_date and p.target_end_date) then r:=jsonb_set(r,'{complete}','false');end if;
 return jsonb_build_object('planId',p.id,'metaRevision',p.meta_revision,'changeSequence',p.change_sequence,'shadowFingerprint',r->>'shadowFingerprint','complete',(r->>'complete')::boolean and (select count(*)<=500 from public.timetable_plan_items where plan_id=p.id) and (select count(*)<=2000 from public.timetable_plan_slots where plan_id=p.id));
end $function$

CREATE OR REPLACE FUNCTION public.get_timetable_plan_v1(p_plan_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.timetable_plans; ref jsonb; items jsonb; slots jsonb; applied jsonb; members jsonb; total_items int; total_slots int; manage boolean; edit boolean;
begin
 perform dashboard_private.timetable_require_v1(p_plan_id);
 select * into p from public.timetable_plans where id=p_plan_id;
 if not found then raise exception using errcode='22023',message='timetable_invalid';end if;
 ref:=dashboard_private.read_timetable_operating_reference_v1();
 if p.target_start_date is not null and exists(select 1 from jsonb_array_elements(ref->'datedUnresolvedOccupancies') b where b->>'date' is null or (b->>'date')::date between p.target_start_date and p.target_end_date) then ref:=jsonb_set(ref,'{complete}','false');end if;
 -- Display-only tombstones retain the original UUID and last saved label.
 ref:=jsonb_set(ref,'{catalogs,teachers}',(ref#>'{catalogs,teachers}')||coalesce((select jsonb_agg(jsonb_build_object('id',x.teacher_catalog_id,'name',x.name,'isVisible',false,'subjects','[]'::jsonb,'isMissing',true) order by x.teacher_catalog_id) from (select s.teacher_catalog_id,max(s.teacher_name) name from public.timetable_plan_slots s where s.plan_id=p_plan_id and not exists(select 1 from public.teacher_catalogs t where t.id=s.teacher_catalog_id) group by s.teacher_catalog_id) x),'[]'::jsonb));
 ref:=jsonb_set(ref,'{catalogs,classrooms}',(ref#>'{catalogs,classrooms}')||coalesce((select jsonb_agg(jsonb_build_object('id',x.classroom_catalog_id,'name',x.name,'isVisible',false,'subjects','[]'::jsonb,'isMissing',true) order by x.classroom_catalog_id) from (select s.classroom_catalog_id,max(s.classroom_name) name from public.timetable_plan_slots s where s.plan_id=p_plan_id and not exists(select 1 from public.classroom_catalogs t where t.id=s.classroom_catalog_id) group by s.classroom_catalog_id) x),'[]'::jsonb));
 select count(*),coalesce(jsonb_agg(dashboard_private.timetable_item_json_v1(i) order by i.id),'[]') into total_items,items from public.timetable_plan_items i where plan_id=p_plan_id;
 select count(*) into total_slots from public.timetable_plan_slots where plan_id=p_plan_id;
 select coalesce(jsonb_agg(dashboard_private.timetable_slot_json_v1(s) order by s.id),'[]') into slots from public.timetable_plan_slots s join public.timetable_plan_items i on i.id=s.item_id where s.plan_id=p_plan_id and i.state='draft';
 select coalesce(jsonb_agg(jsonb_build_object('itemId',i.id,'slots',(select coalesce(jsonb_agg(dashboard_private.timetable_slot_json_v1(s) order by s.id),'[]') from public.timetable_plan_slots s where s.item_id=i.id)) order by i.id),'[]') into applied from public.timetable_plan_items i where i.plan_id=p_plan_id and state='applied';
 select coalesce(jsonb_agg(jsonb_build_object('userId',m.user_id,'name',coalesce(profile.name,''),'access',m.access) order by m.user_id),'[]') into members from public.timetable_plan_members m join public.profiles profile on profile.id=m.user_id where m.plan_id=p_plan_id;
 manage:=dashboard_private.timetable_actor_role_v1() in('admin','staff');
 edit:=manage or exists(select 1 from public.timetable_plan_members where plan_id=p_plan_id and user_id=auth.uid() and access='editor');
 return ref||jsonb_build_object('plan',dashboard_private.timetable_plan_json_v1(p),'items',items,'slots',slots,'appliedSnapshots',applied,'members',members,'permissions',jsonb_build_object('canManage',manage,'canEdit',edit and p.state='draft','canTransfer',manage and p.state='draft'),'capacity',jsonb_build_object('itemCount',total_items,'slotCount',total_slots,'maxItems',500,'maxSlots',2000,'exceeded',total_items>500 or total_slots>2000),'complete',(ref->>'complete')::boolean and total_items<=500 and total_slots<=2000);
end $function$

CREATE OR REPLACE FUNCTION public.initialize_new_class_schedule_v1(p_class_id uuid, p_expected_schedule_revision bigint, p_expected_schedule_plan_hash text, p_slots jsonb, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_class public.classes%rowtype; v_hash text; v_replay jsonb; v_response jsonb;
begin
  perform dashboard_private.lock_timetable_operating_resources_v1();
  perform dashboard_private.assert_continuous_class_schedule_actor_v1(false);
  v_hash := dashboard_private.continuous_class_schedule_hash_v1(jsonb_build_object('classId', p_class_id, 'revision', p_expected_schedule_revision, 'planHash', p_expected_schedule_plan_hash, 'slots', p_slots));
  v_replay := dashboard_private.continuous_class_schedule_request_replay_v1('initialize_new_class_schedule_v1', p_request_key, v_hash);
  if v_replay is not null then declare timetable_result jsonb; begin timetable_result := v_replay; perform dashboard_private.assert_timetable_operational_conflicts_v1(); return timetable_result; end; end if;
  select * into v_class from public.classes where id = p_class_id for update;
  if not found or v_class.schedule_revision <> p_expected_schedule_revision then raise exception 'class_schedule_stale' using errcode = 'P0001'; end if;
  if public.continuous_class_schedule_runtime_version() <> 1 then raise exception 'continuous_class_schedule_runtime_not_ready' using errcode = 'P0001'; end if;
  if v_class.schedule_storage_mode <> 'legacy' or exists(select 1 from public.class_lesson_sessions where class_id = p_class_id)
    or dashboard_private.continuous_class_schedule_hash_v1(coalesce(v_class.schedule_plan, '{}'::jsonb)) <> p_expected_schedule_plan_hash then
    raise exception 'class_schedule_validation' using errcode = '22023';
  end if;
  perform dashboard_private.with_continuous_class_schedule_audit_context_v1(p_class_id, p_request_key, 'initialize_new_class_schedule_v1');
  update public.classes set schedule_storage_mode = 'normalized' where id = p_class_id;
  perform dashboard_private.save_continuous_schedule_defaults_rows_v1(v_class, p_slots);
  select jsonb_build_object('changed', true, 'scheduleRevision', schedule_revision, 'slots', (select coalesce(jsonb_agg(to_jsonb(s)), '[]'::jsonb) from public.class_schedule_slots s where class_id = p_class_id)) into v_response from public.classes where id = p_class_id;
  declare timetable_result jsonb; begin timetable_result := dashboard_private.record_continuous_class_schedule_receipt_v1('initialize_new_class_schedule_v1', p_request_key, v_hash, v_response); perform dashboard_private.assert_timetable_operational_conflicts_v1(); return timetable_result; end;
end;
$function$

CREATE OR REPLACE FUNCTION public.list_timetable_plans_v1(p_search text DEFAULT ''::text, p_archived boolean DEFAULT false, p_page integer DEFAULT 1, p_page_size integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; n int;
begin
 if auth.uid() is null or not coalesce(dashboard_private.timetable_actor_role_v1() in('admin','staff') or dashboard_private.timetable_teacher_eligible_v1(auth.uid()),false) then raise exception using errcode='42501',message='timetable_forbidden';end if;
 if p_page is null or p_page<1 or p_page_size is null or p_page_size not between 1 and 100 then raise exception using errcode='22023',message='timetable_invalid';end if;
 select count(*) into n from public.timetable_plans p where public.can_read_timetable_plan_v1(p.id) and (p_archived or p.state='draft') and p.name ilike '%'||coalesce(p_search,'')||'%';
 select coalesce(jsonb_agg(dashboard_private.timetable_plan_json_v1(p) order by p.updated_at desc,p.id),'[]') into result from (select * from public.timetable_plans x where public.can_read_timetable_plan_v1(x.id) and (p_archived or x.state='draft') and x.name ilike '%'||coalesce(p_search,'')||'%' order by x.updated_at desc,x.id limit p_page_size offset (p_page-1)*p_page_size) p;
 return jsonb_build_object('plans',result,'total',n,'page',p_page,'pageSize',p_page_size,'canManage',dashboard_private.timetable_actor_role_v1() in('admin','staff'));
end $function$

CREATE OR REPLACE FUNCTION public.mutate_timetable_plan_item_v1(p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pid uuid:=(p_command->>'planId')::uuid; iid uuid; op text:=p_command->>'operation'; p public.timetable_plans; old public.timetable_plan_items; i public.timetable_plan_items; v jsonb; s public.timetable_plan_slots; ref jsonb; response jsonb; item jsonb:=p_command->'item'; removed jsonb:='[]'; slots jsonb;
begin
 perform dashboard_private.timetable_require_v1(pid,true,false);
 perform dashboard_private.lock_timetable_operating_resources_v1();
 select * into p from public.timetable_plans where id=pid for update;
 perform dashboard_private.timetable_require_v1(pid,true,false);
 response:=dashboard_private.timetable_receipt_v1('item.'||op,p_command);if response is not null then return response;end if;
 if p.id is null or op not in('save','delete') or op is null or exists(select 1 from jsonb_object_keys(p_command) k where k not in('operation','planId','expectedMetaRevision','expectedShadowFingerprint','expectedItemRevision','requestKey','item','itemId','slots')) then raise exception using errcode='22023',message='timetable_invalid';end if;
 if p.state<>'draft' then raise exception using errcode='42501',message='timetable_forbidden';end if;
 if p.meta_revision is distinct from (p_command->>'expectedMetaRevision')::bigint then raise exception using errcode='P0001',message='timetable_stale';end if;
 iid:=case when op='delete' then (p_command->>'itemId')::uuid else (item->>'id')::uuid end;
 if iid is null then raise exception using errcode='22023',message='timetable_invalid';end if;
 select * into old from public.timetable_plan_items where id=iid for update;
 if old.id is not null and old.plan_id<>pid then raise exception using errcode='22023',message='timetable_invalid';end if;
 if old.state='applied' then raise exception using errcode='42501',message='timetable_forbidden';end if;
 if old.revision is distinct from (p_command->>'expectedItemRevision')::bigint then raise exception using errcode='P0001',message='timetable_stale';end if;
 perform dashboard_private.timetable_check_capacity_v1(pid);
 ref:=dashboard_private.read_timetable_operating_reference_v1();
 if ref->>'shadowFingerprint' is distinct from p_command->>'expectedShadowFingerprint' then raise exception using errcode='P0001',message='timetable_stale';end if;
 if op='delete' then
 if old.id is null then raise exception using errcode='22023',message='timetable_invalid';end if;
 delete from public.timetable_plan_items where id=iid;removed:=jsonb_build_array(iid);slots:='[]';
 else
 if jsonb_typeof(item) is distinct from 'object' or (item->>'planId')::uuid is distinct from pid or exists(select 1 from jsonb_object_keys(item) k where k not in('id','planId','name','subject','subjectAreaKey','grade','capacity','tuition','defaultTeacherId','defaultClassroomId','durationMinutes','pendingSlots')) then raise exception using errcode='22023',message='timetable_invalid';end if;
 if jsonb_typeof(item->'pendingSlots') is distinct from 'array' or jsonb_array_length(item->'pendingSlots')>2000 then raise exception using errcode='22023',message='timetable_invalid';end if;
 for v in select value from jsonb_array_elements(item->'pendingSlots') loop
 if jsonb_typeof(v)<>'object' or v->>'reason' is null or v->>'reason' not in('missing_resource','conflict','invalid_time') or (v->>'id')::uuid is null or jsonb_typeof(v->'sourceText') is distinct from 'string' then raise exception using errcode='22023',message='timetable_invalid';end if;
 end loop;
 perform dashboard_private.validate_timetable_item_slots_v1(pid,iid,item->>'subject',p_command->'slots',ref);
 if (select count(*) from public.timetable_plan_items where plan_id=pid)+(case when old.id is null then 1 else 0 end)>500 or (select count(*) from public.timetable_plan_slots where plan_id=pid and item_id<>iid)+jsonb_array_length(p_command->'slots')>2000 then raise exception using errcode='22023',message='timetable_capacity';end if;
 insert into public.timetable_plan_items(id,plan_id,name,subject,subject_area_key,grade,capacity,tuition,default_teacher_id,default_classroom_id,duration_minutes,pending_slots)
 values(iid,pid,item->>'name',item->>'subject',item->>'subjectAreaKey',coalesce(item->>'grade',''),(item->>'capacity')::int,(item->>'tuition')::int,(item->>'defaultTeacherId')::uuid,(item->>'defaultClassroomId')::uuid,(item->>'durationMinutes')::int,item->'pendingSlots')
 on conflict(id) do update set name=excluded.name,subject=excluded.subject,subject_area_key=excluded.subject_area_key,grade=excluded.grade,capacity=excluded.capacity,tuition=excluded.tuition,default_teacher_id=excluded.default_teacher_id,default_classroom_id=excluded.default_classroom_id,duration_minutes=excluded.duration_minutes,pending_slots=excluded.pending_slots,revision=public.timetable_plan_items.revision+1 returning * into i;
 delete from public.timetable_plan_slots where item_id=iid and id not in(select (x->>'id')::uuid from jsonb_array_elements(p_command->'slots') x);
 for v in select value from jsonb_array_elements(p_command->'slots') loop
 select * into s from public.timetable_plan_slots where id=(v->>'id')::uuid;
 insert into public.timetable_plan_slots(id,plan_id,item_id,weekday,start_minute,end_minute,teacher_catalog_id,classroom_catalog_id,teacher_name,classroom_name,source_slot_id)
 values((v->>'id')::uuid,pid,iid,(v->>'weekday')::int,(v->>'startMinute')::int,(v->>'endMinute')::int,(v->>'teacherId')::uuid,(v->>'classroomId')::uuid,coalesce((select name from public.teacher_catalogs where id=(v->>'teacherId')::uuid),s.teacher_name),coalesce((select name from public.classroom_catalogs where id=(v->>'classroomId')::uuid),s.classroom_name),s.source_slot_id)
 on conflict(id) do update set weekday=excluded.weekday,start_minute=excluded.start_minute,end_minute=excluded.end_minute,teacher_catalog_id=excluded.teacher_catalog_id,classroom_catalog_id=excluded.classroom_catalog_id,teacher_name=excluded.teacher_name,classroom_name=excluded.classroom_name;
 end loop;
 select coalesce(jsonb_agg(dashboard_private.timetable_slot_json_v1(t) order by id),'[]') into slots from public.timetable_plan_slots t where item_id=iid;
 end if;
 update public.timetable_plans set change_sequence=change_sequence+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=pid returning * into p;
 response:=jsonb_build_object('planId',pid,'metaRevision',p.meta_revision,'changeSequence',p.change_sequence,'shadowFingerprint',ref->>'shadowFingerprint','item',case when op='save' then dashboard_private.timetable_item_json_v1(i) else null end,'slots',slots,'removedItemIds',removed);
 perform dashboard_private.timetable_record_receipt_v1('item.'||op,p_command,response);return response;
exception when invalid_text_representation or numeric_value_out_of_range or check_violation or not_null_violation then raise exception using errcode='22023',message='timetable_invalid';
end $function$

CREATE OR REPLACE FUNCTION public.mutate_timetable_plan_v1(p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare op text:=p_command->>'operation'; pid uuid:=(p_command->>'planId')::uuid; sourceid uuid:=(p_command->>'sourcePlanId')::uuid; p public.timetable_plans; src public.timetable_plans; response jsonb; m jsonb; i public.timetable_plan_items; ni uuid;
begin
 if ((p_command ? 'targetStartDate') <> (p_command ? 'targetEndDate')) or ((p_command->>'targetStartDate' is null) <> (p_command->>'targetEndDate' is null)) then raise exception using errcode='22023',message='timetable_invalid';end if;
 perform dashboard_private.timetable_require_v1(pid,false,true);
 perform dashboard_private.lock_timetable_operating_resources_v1();
 perform 1 from public.timetable_plans where id in(pid,sourceid) order by id for update;
 perform dashboard_private.timetable_require_v1(pid,false,true);
 response:=dashboard_private.timetable_receipt_v1('plan.'||op,p_command);if response is not null then return response;end if;
 if pid is null or op is null or op not in('create','rename','clone','share','archive','restore') or exists(select 1 from jsonb_object_keys(p_command) k where k not in('operation','planId','sourcePlanId','expectedMetaRevision','name','targetStartDate','targetEndDate','members','requestKey')) then raise exception using errcode='22023',message='timetable_invalid';end if;
 select * into p from public.timetable_plans where id=pid;
 if op in('create','clone') then
 if p.id is not null then raise exception using errcode='22023',message='timetable_invalid';end if;
 if op='clone' then
 select * into src from public.timetable_plans where id=sourceid;
 if src.id is null then raise exception using errcode='22023',message='timetable_invalid';end if;
 if src.meta_revision is distinct from (p_command->>'expectedMetaRevision')::bigint then raise exception using errcode='P0001',message='timetable_stale';end if;
 perform dashboard_private.timetable_check_capacity_v1(src.id);
 end if;
 insert into public.timetable_plans(id,name,target_start_date,target_end_date,created_by,updated_by) values(pid,p_command->>'name',coalesce((p_command->>'targetStartDate')::date,src.target_start_date),coalesce((p_command->>'targetEndDate')::date,src.target_end_date),auth.uid(),auth.uid()) returning * into p;
 if op='clone' then
 for i in select * from public.timetable_plan_items where plan_id=src.id order by id loop
 ni:=gen_random_uuid();
 insert into public.timetable_plan_items(id,plan_id,name,subject,subject_area_key,grade,capacity,tuition,default_teacher_id,default_classroom_id,duration_minutes,source_class_id,pending_slots)
 values(ni,pid,i.name,i.subject,i.subject_area_key,i.grade,i.capacity,i.tuition,i.default_teacher_id,i.default_classroom_id,i.duration_minutes,coalesce(i.source_class_id,i.applied_class_id),case when i.state='draft' then i.pending_slots else '[]'::jsonb end);
 if i.state='draft' then
 insert into public.timetable_plan_slots(id,plan_id,item_id,weekday,start_minute,end_minute,teacher_catalog_id,classroom_catalog_id,teacher_name,classroom_name,source_slot_id)
 select gen_random_uuid(),pid,ni,weekday,start_minute,end_minute,teacher_catalog_id,classroom_catalog_id,teacher_name,classroom_name,coalesce(source_slot_id,id) from public.timetable_plan_slots where item_id=i.id;
 end if;end loop;end if;
 else
 if p.id is null then raise exception using errcode='22023',message='timetable_invalid';end if;
 if p.meta_revision is distinct from (p_command->>'expectedMetaRevision')::bigint then raise exception using errcode='P0001',message='timetable_stale';end if;
 perform dashboard_private.timetable_check_capacity_v1(pid);
 if p.state='archived' and op not in('restore','share') then raise exception using errcode='42501',message='timetable_forbidden';end if;
 if op='share' then
 if jsonb_typeof(p_command->'members') is distinct from 'array' or (select count(*)<>count(distinct value->>'userId') from jsonb_array_elements(p_command->'members')) then raise exception using errcode='22023',message='timetable_invalid';end if;
 for m in select value from jsonb_array_elements(p_command->'members') loop
 if not dashboard_private.timetable_teacher_eligible_v1((m->>'userId')::uuid) or m->>'access' is null or m->>'access' not in('viewer','editor') or exists(select 1 from jsonb_object_keys(m) k where k not in('userId','access')) then raise exception using errcode='22023',message='timetable_invalid';end if;
 end loop;
 delete from public.timetable_plan_members where plan_id=pid;
 insert into public.timetable_plan_members(plan_id,user_id,access) select pid,(value->>'userId')::uuid,value->>'access' from jsonb_array_elements(p_command->'members');
 end if;
 update public.timetable_plans set name=case when op='rename' then p_command->>'name' else name end,
 target_start_date=case when p_command?'targetStartDate' then (p_command->>'targetStartDate')::date else target_start_date end,
 target_end_date=case when p_command?'targetEndDate' then (p_command->>'targetEndDate')::date else target_end_date end,
 state=case when op='archive' then 'archived' when op='restore' then 'draft' else state end,
 meta_revision=meta_revision+1,change_sequence=change_sequence+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=pid returning * into p;
 end if;
 response:=jsonb_build_object('plan',dashboard_private.timetable_plan_json_v1(p));
 perform dashboard_private.timetable_record_receipt_v1('plan.'||op,p_command,response);return response;
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range or check_violation or not_null_violation then raise exception using errcode='22023',message='timetable_invalid';
end $function$

CREATE OR REPLACE FUNCTION public.save_class_schedule_defaults_v1(p_class_id uuid, p_expected_schedule_revision bigint, p_slots jsonb, p_request_key uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_class public.classes%rowtype; v_hash text; v_replay jsonb; v_change jsonb; v_response jsonb;
begin
  perform dashboard_private.lock_timetable_operating_resources_v1();
  v_hash := dashboard_private.continuous_class_schedule_hash_v1(jsonb_build_object('classId', p_class_id, 'revision', p_expected_schedule_revision, 'slots', p_slots, 'reason', p_reason));
  v_replay := dashboard_private.continuous_class_schedule_request_replay_v1('save_class_schedule_defaults_v1', p_request_key, v_hash);
  if v_replay is not null then declare timetable_result jsonb; begin timetable_result := v_replay; perform dashboard_private.assert_timetable_operational_conflicts_v1(); return timetable_result; end; end if;
  v_class := dashboard_private.require_continuous_class_schedule_mutation_v1(p_class_id, true, true, false, p_reason);
  if v_class.schedule_revision <> p_expected_schedule_revision then raise exception 'class_schedule_stale' using errcode = 'P0001'; end if;
  perform dashboard_private.with_continuous_class_schedule_audit_context_v1(p_class_id, p_request_key, 'save_class_schedule_defaults_v1', p_reason);
  v_change := dashboard_private.save_continuous_schedule_defaults_rows_v1(v_class, p_slots);
  select jsonb_build_object('changed', v_change -> 'changed', 'scheduleRevision', schedule_revision,
    'projectionHash', dashboard_private.continuous_class_schedule_hash_v1(coalesce(schedule_plan, '{}'::jsonb)),
    'slots', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'weekday', weekday, 'startTime', to_char(start_time, 'HH24:MI'), 'endTime', to_char(end_time, 'HH24:MI'), 'teacherCatalogId', teacher_catalog_id, 'teacherName', teacher_name, 'classroomCatalogId', classroom_catalog_id, 'classroomName', classroom_name, 'sortOrder', sort_order) order by weekday, start_time, sort_order), '[]'::jsonb) from public.class_schedule_slots where class_id = p_class_id)
  ) into v_response from public.classes where id = p_class_id;
  declare timetable_result jsonb; begin timetable_result := dashboard_private.record_continuous_class_schedule_receipt_v1('save_class_schedule_defaults_v1', p_request_key, v_hash, v_response); perform dashboard_private.assert_timetable_operational_conflicts_v1(); return timetable_result; end;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_class_operational_v1(p_class_id uuid, p_patch jsonb, p_request_key uuid, p_expected_schedule_plan jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare oldrow public.classes; nextrow public.classes; result jsonb; receipt jsonb; h text; closure jsonb;
begin
 perform dashboard_private.assert_continuous_class_schedule_actor_v1(false);
 perform dashboard_private.lock_timetable_operating_resources_v1();
 if p_class_id is null or p_request_key is null or p_patch='{}'::jsonb or jsonb_typeof(p_patch) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_patch) k where k not in('name','class_type','subject','subject_area_key','grade','teacher','schedule','room','capacity','fee','status','textbook_ids','textbook_usage','schedule_plan')) then raise exception using errcode='22023',message='class_schedule_validation';end if;
 h:=dashboard_private.continuous_class_schedule_hash_v1(jsonb_build_object('classId',p_class_id,'patch',p_patch,'expectedSchedulePlan',p_expected_schedule_plan));
 receipt:=dashboard_private.continuous_class_schedule_request_replay_v1('update_class_operational_v1',p_request_key,h);
 if receipt is not null then return receipt;end if;
 if p_patch->>'status'='종강' then closure:=public.close_class_atomic_v1(p_class_id,p_request_key);end if;
 select * into oldrow from public.classes where id=p_class_id for update;
 if not found then raise exception using errcode='P0002',message='class_schedule_not_found';end if;
 if p_patch ? 'schedule_plan' then
 if oldrow.schedule_storage_mode='normalized' then raise exception using errcode='22023',message='class_schedule_validation';end if;
 if p_expected_schedule_plan is null or coalesce(oldrow.schedule_plan,'{}') is distinct from p_expected_schedule_plan then raise exception using errcode='P0001',message='class_schedule_stale';end if;
 end if;
 if oldrow.schedule_storage_mode='normalized' and (p_patch ?| array['teacher','schedule','room']) then raise exception using errcode='22023',message='class_schedule_validation';end if;
 if p_patch ? 'status' and p_patch->>'status' not in('수강','개강 준비','종강') then raise exception using errcode='22023',message='class_schedule_validation';end if;
 nextrow:=jsonb_populate_record(oldrow,p_patch);
 -- Dynamic SET list is restricted above; omitted operating columns never fire
 -- their statement triggers for a genuine metadata-only request.
 execute format('update public.classes set %s where id=$2 returning to_jsonb(classes)',(select string_agg(format('%I=($1).%I',k,k),', ' order by k) from jsonb_object_keys(p_patch) k)) using nextrow,p_class_id into result;
 perform dashboard_private.assert_timetable_operational_conflicts_v1();
 if not exists(select 1 from dashboard_private.timetable_operating_write_baselines where transaction_id=txid_current()) and (oldrow.name,oldrow.subject,oldrow.grade) is distinct from (nextrow.name,nextrow.subject,nextrow.grade) then
 update public.timetable_invalidation_signals set change_sequence=change_sequence+1,updated_at=clock_timestamp() where id='operating';end if;
 return dashboard_private.record_continuous_class_schedule_receipt_v1('update_class_operational_v1',p_request_key,h,jsonb_build_object('classRow',result,'closeResult',closure));
end $function$
